issue_context.body:
**Describe the bug**

If a React hook call isn't assigned but instead used in an expression, then the refresh transformer doesn't seem to recognize it and create a hash.

(This is a valid hook call, and the React Hooks eslint rule doesn't complain)

**Input code**

```js
import { useState } from "react";

export function App() {
	console.log(useState())

	return null;
}
```


**Config**

```json
{
  "jsc": {
    "parser": {
      "syntax": "ecmascript",
      "jsx": true
    },
    "transform": {
      "react": {
        "refresh": true,
        "development": true
      }
    }
  }
}

```

**Current behaviour** 

```js
import { useState } from "react";
export function App() {
    console.log(useState());
    return null;
}
_c = App;
var _c;
$RefreshReg$(_c, "App");
```

**Expected behavior**
With the offical `react-refresh/babel` plugin:

```js
var _s = $RefreshSig$();

import { useState } from "react";
export function App() {
  _s();

  console.log(useState());
  return null;
}

_s(App, "VhlnxxH3xh7Qs17KADUJ8wvRSZs=");

_c = App;

var _c;

$RefreshReg$(_c, "App");
```

**Version**
20ce326909670d0e40c9f1bbd804387c2958eae6
